import type { Argv, ArgumentsCamelCase } from 'yargs'
import { cwd } from 'process'
import * as fs from 'fs'
import { validateWorkingDir } from '../../util'
import { logger } from '../../logger'
import { createTelemetryClient } from '../../telemetry'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'
import { credentialProvider } from '../../auth'

interface Arguments {
    script: string
    cwd: string
    auth: string | undefined
}

export function builder(yargs: Argv) {
    return yargs
        .positional('script', {
            describe: 'Name of the script to run',
            type: 'string',
        })
        .demandOption('script')
        .positional('cwd', {
            describe: 'The working directory to run the script in',
            default: cwd(),
            type: 'string',
        })
        .option('auth', {
            describe: 'Credential alias to use for authentication with instance',
            type: 'string',
            alias: 'a',
        })
        .strict(false)
}

export async function handler(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    const credential = await credentialProvider(args.auth)
    const telemetryClient = createTelemetryClient(__dirname)

    try {
        const workingDir = validateWorkingDir(args.cwd)

        const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

        // A normal run is reported by Orchestrator.run()'s own `run` event; this only
        // captures the case where the user interrupts a long-running script with Ctrl+C.
        process.on('SIGINT', async () => {
            telemetryClient.capture('run.interrupted', {
                scope_id: config.scopeId,
            })
            await telemetryClient.flush()
            process.exit(0)
        })

        const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })

        const orchestrator = new Orchestrator(project, credential)

        const { script: _script, cwd: _cwd, auth: _auth, a: _a, _: _positional, $0: _$0, ...scriptArgs } = args

        await orchestrator.run({ script: args.script, args: scriptArgs })
    } catch (error) {
        logger.error('Error running script:', error)

        process.exitCode = 1 // set exit code to 1 to indicate failure for CI
    }
}
